CREATE TYPE "public"."finance_decision_next" AS ENUM('receipt_within_7d', 'cap_amount', 'use_camp_supplier', 'resubmit_lower', 'next_budget_round', 'ask_camp_lead', 'already_covered', 'borrow_kit', 'move_budget', 'close');--> statement-breakpoint
CREATE TYPE "public"."finance_decision_reason" AS ENUM('within_budget', 'essential', 'approved_with_condition', 'need_quote', 'need_cheaper', 'purpose_unclear', 'over_budget', 'not_needed', 'wrong_budget', 'other');--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD COLUMN "reason_code" "finance_decision_reason";--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD COLUMN "next_step" "finance_decision_next";--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD COLUMN "cap_amount_cents" bigint;--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD COLUMN "moved_to_budget_id" uuid;--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD CONSTRAINT "finance_request_steps_moved_to_budget_id_finance_budgets_id_fk" FOREIGN KEY ("moved_to_budget_id") REFERENCES "public"."finance_budgets"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
-- Back-fill: steps decided before reason codes become "other" with a note (demo data only).
UPDATE "finance_request_steps" SET "reason_code" = 'other', "comment" = coalesce(nullif(btrim("comment"), ''), 'Decided before reason codes') WHERE "status" <> 'pending';--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD CONSTRAINT "finance_request_steps_reason_ck" CHECK (("finance_request_steps"."status" = 'pending') = ("finance_request_steps"."reason_code" is null) and ("finance_request_steps"."reason_code" is distinct from 'other' or coalesce(btrim("finance_request_steps"."comment"), '') <> '') and ("finance_request_steps"."reason_code" is null or "finance_request_steps"."reason_code" = 'other' or ("finance_request_steps"."status" = 'approved' and "finance_request_steps"."reason_code" in ('within_budget', 'essential', 'approved_with_condition')) or ("finance_request_steps"."status" = 'needs_info' and "finance_request_steps"."reason_code" in ('need_quote', 'need_cheaper', 'purpose_unclear')) or ("finance_request_steps"."status" = 'rejected' and "finance_request_steps"."reason_code" in ('over_budget', 'not_needed', 'wrong_budget'))));--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD CONSTRAINT "finance_request_steps_next_ck" CHECK (coalesce(("finance_request_steps"."next_step" is null and "finance_request_steps"."reason_code" is distinct from 'approved_with_condition') or ("finance_request_steps"."reason_code" = 'approved_with_condition' and "finance_request_steps"."next_step" in ('receipt_within_7d', 'cap_amount', 'use_camp_supplier')) or ("finance_request_steps"."reason_code" = 'over_budget' and "finance_request_steps"."next_step" in ('resubmit_lower', 'next_budget_round', 'ask_camp_lead')) or ("finance_request_steps"."reason_code" = 'not_needed' and "finance_request_steps"."next_step" in ('already_covered', 'borrow_kit', 'close')) or ("finance_request_steps"."reason_code" = 'wrong_budget' and "finance_request_steps"."next_step" in ('move_budget', 'ask_camp_lead', 'close')), false));--> statement-breakpoint
ALTER TABLE "finance_request_steps" ADD CONSTRAINT "finance_request_steps_next_detail_ck" CHECK (("finance_request_steps"."next_step" = 'cap_amount') = ("finance_request_steps"."cap_amount_cents" is not null and "finance_request_steps"."cap_amount_cents" > 0) and ("finance_request_steps"."next_step" = 'move_budget') = ("finance_request_steps"."moved_to_budget_id" is not null));